create type public.assessment_type as enum ('placement','progress','final','certification_readiness','skill_check');
create table public.assessment_tests(id uuid primary key default gen_random_uuid(),code text not null unique,language text not null check(language in ('English','Japanese','German')),framework text not null,level text not null,test_type assessment_type not null,title text not null,description text not null,duration_minutes int not null check(duration_minutes between 5 and 240),pass_score numeric not null check(pass_score between 0 and 100),published boolean not null default true,created_at timestamptz not null default now());
create table public.assessment_questions(id uuid primary key default gen_random_uuid(),test_id uuid not null references assessment_tests(id) on delete cascade,prompt text not null,options jsonb not null,correct_option text not null,points numeric not null default 1,sort_order int not null);
create table public.assessment_attempts(id uuid primary key default gen_random_uuid(),test_id uuid not null references assessment_tests(id),student_id uuid not null references profiles(id),started_at timestamptz not null default now(),submitted_at timestamptz,score numeric,max_score numeric,status text not null default 'in_progress',unique(test_id,student_id,started_at));
create table public.assessment_answers(attempt_id uuid references assessment_attempts(id) on delete cascade,question_id uuid references assessment_questions(id),answer text,correct boolean not null,points_awarded numeric not null default 0,primary key(attempt_id,question_id));
alter table assessment_tests enable row level security;alter table assessment_questions enable row level security;alter table assessment_attempts enable row level security;alter table assessment_answers enable row level security;
create policy tests_public_read on assessment_tests for select using(published or is_staff());
create policy questions_staff_only on assessment_questions for select using(is_staff());
create policy attempts_owner_read on assessment_attempts for select using(student_id=auth.uid() or is_staff());
create policy answers_owner_read on assessment_answers for select using(is_staff() or exists(select 1 from assessment_attempts a where a.id=attempt_id and a.student_id=auth.uid()));
create policy tests_staff_manage on assessment_tests for all using(current_role() in ('academic','admin','superadmin')) with check(current_role() in ('academic','admin','superadmin'));
create policy questions_staff_manage on assessment_questions for all using(current_role() in ('academic','admin','superadmin')) with check(current_role() in ('academic','admin','superadmin'));

